import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Stage 5 · Memory & Evolution","description":"Hearth Stage 5 development module: Memory Core, memory browser, conflict and forgetting, trajectory mining, skill candidates, evaluation, promotion, and rollback.","frontmatter":{"title":"Stage 5 · Memory & Evolution","description":"Hearth Stage 5 development module: Memory Core, memory browser, conflict and forgetting, trajectory mining, skill candidates, evaluation, promotion, and rollback.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-5.md","filePath":"en/delivery/stage-5.md","lastUpdated":null}'),i={name:"en/delivery/stage-5.md"};function n(l,e,s,d,c,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<p class="eyebrow">MODULE 5 / 7</p><h1 id="stage-5-·-memory-evolution" tabindex="-1">Stage 5 · Memory &amp; Evolution <a class="header-anchor" href="#stage-5-·-memory-evolution" aria-label="Permalink to &quot;Stage 5 · Memory &amp; Evolution&quot;">​</a></h1><p class="lead">Accumulate personal context and improve methods without turning memory contamination or skill drift into an unexplainable black box. Make memory correctable, then forgettable, then skills evaluable, and only then promotable.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Task provenance, permissions, and approval boundaries are stable; sensitive data is classified.</li><li>Memory writes, retrieval, and injection cannot bypass a Mandate or expand permissions.</li><li>Representative tasks, success/failure samples, and a repeatable evaluation set exist.</li></ul><h2 id="development-steps" tabindex="-1">Development Steps <a class="header-anchor" href="#development-steps" aria-label="Permalink to &quot;Development Steps&quot;">​</a></h2><ol><li><strong>Deliver Memory Core.</strong> Implement the five memory types with source, sensitivity, time, confidence, scope, and retrieval budget; add a memory browser and &quot;why was this recalled&quot; view.</li><li><strong>Handle conflict and forgetting.</strong> Implement write conflicts, correction, deletion, tombstones, forgetting propagation, export, and data migration.</li><li><strong>Mine trajectories and skill candidates.</strong> Extract reusable methods from real trajectories into candidates with versions, permissions, and evaluation sets; never expand permissions automatically.</li><li><strong>Build evaluation and promotion gates.</strong> Run Shadow, Canary, Promote, and Rollback with controlled evaluation, security regression, and human review.</li><li><strong>Complete the first promotion case.</strong> Take at least one skill through candidate, evaluation, trial, promotion, and rollback, and explain it to the user.</li><li><strong>Complete the Stage 5 release.</strong> Evaluate memory accuracy, injection quality, forgetting, export, skill benefit, permissions, and security regressions.</li></ol><h2 id="increment-breakdown" tabindex="-1">Increment Breakdown <a class="header-anchor" href="#increment-breakdown" aria-label="Permalink to &quot;Increment Breakdown&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Increment</th><th>User-visible outcome</th><th>Completion evidence</th></tr></thead><tbody><tr><td>D5.1 Memory Core and browser</td><td>Users can inspect, understand, and correct memory in use</td><td>Five memory types, provenance, budgets, recall explanation</td></tr><tr><td>D5.2 Conflict, forgetting, and export</td><td>Wrong memory is correctable, forgetting propagates, data is exportable</td><td>Tombstones, propagation, export, migration tests</td></tr><tr><td>D5.3 Trajectories, skill candidates, evaluation sets</td><td>The system proposes reusable methods from work</td><td>Trajectory mining, candidates, versions, evaluation samples</td></tr><tr><td>D5.4 Evolution gate and release</td><td>New methods have comparative evidence and rollback</td><td>Shadow, Canary, Promote, Rollback case</td></tr></tbody></table><h2 id="exit-checklist" tabindex="-1">Exit Checklist <a class="header-anchor" href="#exit-checklist" aria-label="Permalink to &quot;Exit Checklist&quot;">​</a></h2><ul><li>[ ] Memory is explainable, correctable, forgettable, exportable, and forgetting propagates.</li><li>[ ] Memory injection accuracy meets the target; sensitive data stays out of disallowed contexts.</li><li>[ ] Skill promotion has controlled evaluation; evolution never expands permissions.</li><li>[ ] At least one skill completes promotion and rollback.</li><li>[ ] Users understand why a memory was recalled or a new method was adopted.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Self-evolution without provenance, evaluation, or rollback.</li><li>Memory poisoning that changes permissions, approval policy, or system facts.</li><li>Replacing repeatable evaluation with &quot;the model thinks it is useful.&quot;</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Continue to <a href="/hearth-os/en/delivery/stage-6.html">Stage 6 · Multi-device &amp; Operations</a> to turn the local product into a long-running, portable Personal Agent OS.</p>',15)])])}const h=t(i,[["render",n]]);export{u as __pageData,h as default};
